// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WebDAVResource) predicate.WebDAVResource {
	return predicate.WebDAVResource(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WebDAVResource) predicate.WebDAVResource {
	return predicate.WebDAVResource(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WebDAVResource) predicate.WebDAVResource {
	return predicate.WebDAVResource(sql.NotPredicates(p))
}
